import os
import torch


class Config:
    # =========================================================================
    # Paths
    # =========================================================================
    # Metadata paths (generated by the metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching processed data and saving models
    # Using 'idea_2' as per the working directory info in the prompt
    WORK_DIR = "./working/idea_2"

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Hyperparameters
    # =========================================================================
    VOCAB_SIZE = 60000  # Top K frequent words
    MIN_FREQ = 2  # Minimum frequency to be included in vocab
    MAX_SEQ_LEN = 128  # Maximum sequence length (covers most sentences)

    # Special Tokens
    PAD_TOKEN = "[PAD]"
    UNK_TOKEN = "[UNK]"
    NO_INSERT_TOKEN = "[NO_INSERT]"  # Target label for positions with no insertion

    # =========================================================================
    # Model Architecture
    # =========================================================================
    # Transformer Encoder parameters
    D_MODEL = 512  # Embedding dimension
    N_HEAD = 8  # Number of attention heads
    N_LAYERS = 6  # Number of encoder layers
    DIM_FEEDFORWARD = 2048  # Feedforward dimension
    DROPOUT = 0.1  # Dropout rate
    ACTIVATION = "gelu"  # Activation function

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42
    BATCH_SIZE = 512  # Large batch size for A100
    NUM_WORKERS = 12  # Number of dataloader workers (matches vCPUs)

    # Optimization
    LEARNING_RATE = 5e-4  # Peak learning rate for OneCycle
    WEIGHT_DECAY = 0.01  # Weight decay for AdamW
    EPOCHS = 10  # Maximum number of epochs
    PATIENCE = 2  # Early stopping patience

    # Loss weighting
    # We down-weight the [NO_INSERT] class because it is the majority class
    NO_INSERT_WEIGHT = 0.05

    # =========================================================================
    # Compute
    # =========================================================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    USE_AMP = True  # Use Automatic Mixed Precision

    @classmethod
    def setup(cls):
        """
        Creates necessary directories and sets random seeds.
        """
        os.makedirs(cls.WORK_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seeds for reproducibility
        import random
        import numpy as np

        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        torch.cuda.manual_seed_all(cls.SEED)

        # Deterministic operations where possible
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False


# Initialize setup immediately when config is imported to ensure directories exist
Config.setup()
